how_to_use:
showDialog(
  context: context,
  builder: (context) {
    return AlertDialog(
      title: Text('Delete Item'),
      content: Text('Are you sure you want to delete this item?'),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: () {
            // Perform delete
            Navigator.pop(context);
          },
          child: Text('Delete'),
        ),
      ],
    );
  },
);
